mapper.select:
select r.*,
  (select count(*) from todo_template_draft_rule_ref ref
   where ref.ref_type='SLA' and ref.ref_id_value=r.sla_rule_id) reference_count
from todo_sla_rule r

  r.status=#{status}
  and r.sla_type=#{slaType}
  and (r.rule_code like concat('%',#{keyword},'%') or r.rule_name like concat('%',#{keyword},'%'))
  and r.update_time >= #{beginTime}
  and r.update_time <= #{endTime}

order by r.update_time desc,r.sla_rule_id desc

mapper.update:
update todo_sla_rule
rule_code=#{ruleCode},rule_name=#{ruleName},sla_type=#{slaType},duration_value=#{durationValue}, duration_unit=#{durationUnit},calendar_code=#{calendarCode},start_strategy=#{startStrategy}, soft_remind_percent=#{softRemindPercent},hard_remind_percent=#{hardRemindPercent},escalate_percent=#{escalatePercent}, pause_policy_json=cast(#{pausePolicyJson} as json),escalation_policy_json=cast(#{escalationPolicyJson} as json), auto_action_json=cast(#{autoActionJson} as json),status=#{status}, status=#{status}, update_by=#{updateBy},update_time=sysdate(),version=version+1
where sla_rule_id=#{slaRuleId} and version=#{expectedVersion}

mapper.select:
select r.*,
  (select count(*) from todo_template_draft_rule_ref ref
   where ref.ref_type='DOD' and ref.ref_id_value=r.dod_rule_id) reference_count
from todo_dod_rule r

  r.status=#{status}
  and r.rule_type=#{ruleType}
  and (r.rule_code like concat('%',#{keyword},'%') or r.rule_name like concat('%',#{keyword},'%'))
  and r.update_time >= #{beginTime}
  and r.update_time <= #{endTime}

order by r.update_time desc,r.dod_rule_id desc

select v.*,coalesce(v.published_time,v.create_time) update_time,t.template_code,t.template_name,t.business_type,
  action.action_id,action.action_type,action.operator_id,action.operator_name,action.create_time action_create_time
from todo_template_version v join todo_template t on t.template_id=v.template_id
left join todo_definition_action action on action.definition_action_id=(
  select candidate.definition_action_id from todo_definition_action candidate
  where candidate.source_entity_id=v.version_id and candidate.entity_type='VERSION'
    and candidate.action_type='PUBLISH_VERSION'
  order by candidate.create_time desc,candidate.definition_action_id desc limit 1)

  v.status in ('PUBLISHED','RETIRED')
  and v.status=#{status}
  and v.published_by=#{publisher}
  and v.template_id=#{templateId}
  and t.template_code=#{templateCode}
  and (t.template_code like concat('%',#{keyword},'%') or t.template_name like concat('%',#{keyword},'%'))
  and coalesce(v.published_time,v.create_time) >= #{beginTime}
  and coalesce(v.published_time,v.create_time) <= #{endTime}

order by coalesce(v.published_time,v.create_time) desc,v.version_id desc
limit #{limit} offset #{offset}

select c.*,(select count(*) from todo_trigger_rule r where r.event_type=c.event_type
  and r.payload_version=c.payload_version) reference_count
from todo_event_catalog c where c.event_catalog_id=#{id}

select 'TRIGGER_RULE' reference_type,r.trigger_rule_id reference_id,r.rule_code reference_code,
  r.rule_name reference_name,case when r.enabled='Y' then 'ENABLED' else 'DISABLED' end reference_status
from todo_trigger_rule r where r.event_type=#{eventType} and r.payload_version=#{payloadVersion}
union all
select 'TEMPLATE_VERSION',v.version_id,t.template_code,t.template_name,v.status
from todo_template_version v join todo_template t on t.template_id=v.template_id
where json_unquote(json_extract(v.definition_json,'$.event.eventType'))=#{eventType}
  and coalesce(cast(json_unquote(json_extract(v.definition_json,'$.event.payloadVersion')) as unsigned),1)=#{payloadVersion}
order by reference_type,reference_id

select t.template_code from todo_template_version v
join todo_template t on t.template_id=v.template_id
where v.version_id=#{versionId}

select t.template_id,t.template_code,t.business_type
from todo_template_version v join todo_template t on t.template_id=v.template_id
where v.version_id=#{versionId}

select * from todo_simulation_evidence
where template_id=#{templateId} and version_id=#{versionId}
  and scenario_code=#{scenarioCode} and scenario_version=#{scenarioVersion}
order by executed_time desc,evidence_id desc limit 1
